 "content": "def transform(grid):
    # Blue/marked shape is overlaid onto occurrences of its underlying
    # background pattern throughout the grid. The demo establishes this as
    # translating a 3x3 motif (zeros in motif map to background) to matching
    # neighborhoods; implement the direct pattern marker overlay.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The motif is the connected component of the unique non-background
    # marker color; its coordinates relative to its bounding box define stencil.
    colors = {v for row in grid for v in row}
    marker = next((c for c in colors if c not in (0, 7)), None)
    bg = 7 if 7 in colors else 0
    if marker is None:
        return out
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    stencil = {(r-r0,c-c0) for r,c in pts}
    # Candidate occurrences are all translated stencil bounding boxes whose
    # cells are background or stencil-marked color; paint stencil positions.
    sh, sw = r1-r0+1, c1-c0+1
    for dr in range(h-sh+1):
        for dc in range(w-sw+1):
            if all(grid[dr+u][dc+v] == bg for u,v in stencil):
                continue
            # Demo has distinct pattern match selected by the exact stencil occupancy
            if all((grid[dr+u][dc+v] != bg) == ((u,v) in stencil)
                   for u in range(sh) for v in range(sw)):
                for u,v in stencil:
                    out[dr+u][dc+v] = marker
    return out
